('8c5dabbb-acd4-440a-a560-ac91f7d995c1', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT event_object_table, trigger_name, event_manipulation, action_statement\\nFROM information_schema.triggers\\nWHERE event_object_table = ''leads''", "paramCount": 0, "rowsAffected": 0}', '49.37.11.56', '2026-03-05 07:01:07.69488+00', '2026-03-05 07:01:07.69488+00'),
('8082c5f9-d0f6-42ac-a60d-c2e1e65b8b49', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT column_name, data_type FROM information_schema.columns WHERE table_name = ''campaign_stats'' ORDER BY ordinal_position", "paramCount": 0, "rowsAffected": 5}', '49.37.11.56', '2026-03-05 07:01:15.238672+00', '2026-03-05 07:01:15.238672+00'),
('fcc7ea11-06e3-4027-b6f7-df89e6688f3c', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "CREATE OR REPLACE FUNCTION update_campaign_stats_trigger()\\nRETURNS TRIGGER AS $$\\nBEGIN\\n    INSERT INTO campaign_stats (campaign_id, total_sent, total_replied, reply_rate, last_synced_at)\\n    SELECT \\n        NEW.campaign_id,\\n        COALESCE(SUM(CASE WHEN status IN (''SENT'', ''REPLIED'') THEN 1 ELSE 0 E", "paramCount": 0}', '49.37.11.56', '2026-03-05 07:01:44.378422+00', '2026-03-05 07:01:44.378422+00'),
('f08b8ce6-ac0d-431c-b383-240963baddbe', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "INSERT INTO campaign_stats (campaign_id, total_sent, total_replied, reply_rate, last_synced_at)\\nSELECT \\n    campaign_id,\\n    COALESCE(SUM(CASE WHEN status IN (''SENT'', ''REPLIED'') THEN 1 ELSE 0 END), 0) as total_sent,\\n    COALESCE(SUM(CASE WHEN status = ''REPLIED'' THEN 1 ELSE 0 END), 0) as total_replie", "paramCount": 0, "rowsAffected": 6}', '49.37.11.56', '2026-03-05 07:01:55.272586+00', '2026-03-05 07:01:55.272586+00'),
('5d42e336-61c2-4db6-9932-784cde99796f', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT count(*) FROM replies", "paramCount": 0, "rowsAffected": 1}', '49.37.11.56', '2026-03-05 07:07:20.139021+00', '2026-03-05 07:07:20.139021+00'),
