('65d27051-1d24-4bde-98f4-d6170861fd40', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "ALTER TABLE sender_accounts ADD COLUMN IF NOT EXISTS name TEXT;\\n\\n-- Backfill existing accounts by fetching actual name from Gmail won''t work here directly,\\n-- but we can set a friendly display based on the email prefix for now.\\nUPDATE sender_accounts SET name = split_part(email, ''@'', 1) WHERE name I", "paramCount": 0}', '49.37.11.56', '2026-03-05 07:30:06.829879+00', '2026-03-05 07:30:06.829879+00'),
