('0957697a-4681-427a-8118-ea0f8979b602', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "CREATE OR REPLACE FUNCTION update_lead_status_from_webhook(\\n    p_campaign_id UUID,\\n    p_email TEXT,\\n    p_event TEXT,\\n    p_gmail_message_id TEXT DEFAULT NULL,\\n    p_gmail_thread_id TEXT DEFAULT NULL\\n) RETURNS JSONB\\nLANGUAGE plpgsql\\nSECURITY DEFINER -- This bypasses RLS as it runs as the function ", "paramCount": 0, "rowsAffected": null}', '49.37.11.56', '2026-03-05 15:08:01.817657+00', '2026-03-05 15:08:01.817657+00'),
('60dc2d96-8721-4863-8ae5-7028e0084d16', 'admin@insforge.local', 'GET_SECRET', 'SECRETS', '{"key": "API_KEY"}', '18.223.136.193', '2026-03-05 18:55:39.543641+00', '2026-03-05 18:55:39.543641+00'),
