('4234ff42-d4fd-465d-b082-4b73c92253d6', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    sa.email,\\n    ws.sent,\\n    ws.received,\\n    ws.replies,\\n    ws.spam_rescues,\\n    ws.date\\nFROM warmup_stats ws\\nJOIN warmup_accounts wa ON ws.account_id = wa.id\\nJOIN sender_accounts sa ON wa.gmail_account_id = sa.id\\nWHERE ws.date = CURRENT_DATE\\nORDER BY sa.email;", "paramCount": 0, "rowsAffected": 0}', '49.37.11.64', '2026-03-20 06:25:11.675369+00', '2026-03-20 06:25:11.675369+00'),
('d859743b-7f1f-4c6c-b9b9-da4a95805932', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    DATE(we.sent_at) as date,\\n    COUNT(*) as emails_sent\\nFROM warmup_emails we\\nGROUP BY DATE(we.sent_at)\\nORDER BY DATE(we.sent_at) DESC\\nLIMIT 7;", "paramCount": 0, "rowsAffected": 2}', '49.37.11.64', '2026-03-20 06:25:12.265678+00', '2026-03-20 06:25:12.265678+00'),
