('5bada963-cda4-4cb9-ab3d-e738f30edf0a', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    wj.id,\\n    wj.scheduled_at,\\n    wj.status,\\n    sa.email as account_email,\\n    wa.day_number\\nFROM warmup_jobs wj\\nJOIN warmup_accounts wa ON wj.warmup_account_id = wa.id\\nJOIN sender_accounts sa ON wa.gmail_account_id = sa.id\\nWHERE wj.status = ''pending''\\nORDER BY wj.scheduled_at\\nLIMIT 5;", "paramCount": 0, "rowsAffected": 0}', '49.37.11.64', '2026-03-20 06:28:21.391951+00', '2026-03-20 06:28:21.391951+00'),
