('26f3856d-e62f-4fb4-9f3a-8b2fd42c079e', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    COUNT(*) as pending_replies,\\n    MIN(scheduled_at) as earliest_reply,\\n    MAX(scheduled_at) as latest_reply\\nFROM pending_replies \\nWHERE status = ''pending''\\nAND scheduled_at > NOW();", "paramCount": 0, "rowsAffected": 1}', '49.37.11.64', '2026-03-20 07:06:34.515518+00', '2026-03-20 07:06:34.515518+00')
INSERT INTO system.audit_logs (id, actor, action, module, details, ip_address, created_at, updated_at) VALUES
('c0bc3561-1959-4b54-a6d0-469c49b2b00e', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    COUNT(*) as pending_replies,\\n    COUNT(*) FILTER (WHERE scheduled_at <= NOW()) as ready_to_send,\\n    COUNT(*) FILTER (WHERE status = ''failed'') as failed_replies\\nFROM pending_replies;", "paramCount": 0, "rowsAffected": 1}', '49.37.11.64', '2026-03-20 11:03:02.506591+00', '2026-03-20 11:03:02.506591+00'),
('8d2c6990-289d-46a0-930c-421d047305ba', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    sa.email,\\n    ws.sent,\\n    ws.received,\\n    ws.replies,\\n    ws.spam_rescues,\\n    wa.day_number,\\n    wa.persona\\nFROM warmup_stats ws\\nJOIN warmup_accounts wa ON ws.account_id = wa.id\\nJOIN sender_accounts sa ON wa.gmail_account_id = sa.id\\nWHERE ws.date = CURRENT_DATE\\nORDER BY ws.sent DESC;", "paramCount": 0, "rowsAffected": 9}', '49.37.11.64', '2026-03-20 11:03:02.510279+00', '2026-03-20 11:03:02.510279+00'),
