('579d50d8-4e2f-4d6c-b87b-c8975742b6b3', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    status,\\n    COUNT(*) as count\\nFROM pending_replies\\nGROUP BY status\\nORDER BY status;", "paramCount": 0, "rowsAffected": 2}', '49.37.11.64', '2026-03-20 11:03:37.604553+00', '2026-03-20 11:03:37.604553+00'),
('d8ed3539-ad84-43ae-92b0-2df994f8ad16', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    sa.email,\\n    COUNT(DISTINCT we.from_account_id) as unique_senders,\\n    COUNT(*) as total_received\\nFROM warmup_emails we\\nJOIN warmup_accounts wa ON we.to_account_id = wa.id\\nJOIN sender_accounts sa ON wa.gmail_account_id = sa.id\\nWHERE DATE(we.sent_at) = CURRENT_DATE\\nGROUP BY sa.email\\nORDE", "paramCount": 0, "rowsAffected": 9}', '49.37.11.64', '2026-03-20 11:03:50.689563+00', '2026-03-20 11:03:50.689563+00'),
('22d2f5d1-51e9-48bf-a0c1-b7e1a93a77f6', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "\\n-- Simulate what PostgREST does with the inbox query\\n-- First get the user''s campaigns\\nSELECT id FROM campaigns LIMIT 1;\\n", "paramCount": 0, "rowsAffected": 1}', '49.37.8.122', '2026-03-22 14:02:02.094265+00', '2026-03-22 14:02:02.094265+00'),
('cd4334b1-820a-4d86-8653-edae0d9f12a5', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    we.subject,\\n    we.status,\\n    sa.email as from_email,\\n    we.sent_at\\nFROM warmup_emails we\\nJOIN warmup_accounts wa ON we.from_account_id = wa.id\\nJOIN sender_accounts sa ON wa.gmail_account_id = sa.id\\nORDER BY we.sent_at DESC\\nLIMIT 20;", "paramCount": 0, "rowsAffected": 20}', '49.37.11.64', '2026-03-20 12:16:25.398565+00', '2026-03-20 12:16:25.398565+00'),
('b64e3f06-3cfa-4f8f-95be-42fbf6d60fd4', 'api-key', 'EXECUTE_RAW_SQL', 'DATABASE', '{"mode": "strict", "query": "SELECT \\n    ws.date,\\n    ws.sent,\\n    ws.received,\\n    ws.replies,\\n    sa.email\\nFROM warmup_stats ws\\nJOIN warmup_accounts wa ON ws.account_id = wa.id\\nJOIN sender_accounts sa ON wa.gmail_account_id = sa.id\\nWHERE sa.email = ''demgrowonline@gmail.com''\\nORDER BY ws.date DESC\\nLIMIT 7;", "paramCount": 0, "rowsAffected": 3}', '49.37.11.64', '2026-03-20 13:49:37.242585+00', '2026-03-20 13:49:37.242585+00')
